INSERT INTO PLAYLISTS (CANAL_ID, YT_PLAYLIST_ID, TITULO, QTD_YT, ORDEM, SINC, ATUALIZADO_EM) SELECT {{canalId}}, PID, TITULO, QTD, ORDEM, '{{sinc}}', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM VW_LOTE_PLAYLISTS WHERE CHAVE = '{{chave}}' ON DUPLICATE KEY UPDATE TITULO = VALUES(TITULO), QTD_YT = VALUES(QTD_YT), ORDEM = VALUES(ORDEM), SINC = VALUES(SINC), ATUALIZADO_EM = VALUES(ATUALIZADO_EM)